export const guideData="/* Original SHIFT food ideas. Guidance checked 12 October 2026. */\nwindow.SHIFT_DATA = {\n sources:{\n  balanced:{name:'NHS · Eating a balanced diet',url:'https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/eating-a-balanced-diet/',date:'Reviewed 30 June 2026',scope:'General food groups, variety, wholegrains, protein foods and dairy alternatives.'},\n  fibre:{name:'NHS · Getting more fibre',url:'https://www.nhs.uk/live-well/eat-well/digestive-health/how-to-get-more-fibre-into-your-diet/',date:'Reviewed 2 March 2026',scope:'General adult fibre guidance, not a personal target.'},\n  vegan:{name:'NHS · The vegan diet',url:'https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/the-vegan-diet/',date:'Reviewed 5 June 2026',scope:'A vegan diet needs planning and reliable nutrient sources. These meals do not establish nutritional adequacy.'},\n  glp1:{name:'BDA · Eating and living well with medications for obesity',url:'https://www.bda.uk.com/food-health/glp-1-obesity-medications.html',date:'Main resource © February 2026; review due 2027',scope:'General dietetic advice for GLP-1-type medicines. BDA discloses manufacturer funding with no input into content.'},\n  safety:{name:'Food Standards Agency · Cooking your food',url:'https://www.gov.uk/government/publications/cooking-your-food/cooking-your-food',date:'Official food-safety guidance; checked 12 October 2026',scope:'Cooking, reheating and food-safety principles. Always follow pack and appliance instructions.'}\n },\n goals:{\n  basics:{title:'Start with a meal you already eat.',body:'Keep the familiar bit. Add some variety around it. You don’t have to rebuild your whole week.',steps:['Give protein foods, starchy foods and fruit or veg a place across your meals.','Choose one idea below. Change the amounts to suit you.']},\n  smaller:{title:'Use the appetite you have.',body:'Try a manageable amount and take your time. A smaller meal can still include variety.',steps:['Keep a protein food in the meal.','Amounts below are adjustable; they are not personal targets.']},\n  budget:{title:'Check the cupboard before the shop.',body:'Beans, lentils, oats, frozen veg and tinned produce can do useful work. You may already have the start of a meal.',steps:['Ideas marked “Cupboard friendly” appear first.','Tick what you have; decide what is missing. No prices or savings are assumed.']},\n  quick:{title:'Keep one easy meal in reserve.',body:'A short ingredient list and a familiar method can help on a busy day.',steps:['Quicker ideas appear first within each meal.','Kitchen times are estimates, not a promise about your day.']},\n  protein:{title:'Give protein foods a place.',body:'Start with everyday choices such as beans, lentils, eggs, yoghurt, fish or tofu. Pick something you enjoy and can repeat.',steps:['Choose the version of a meal that fits how you eat.','This guide does not calculate protein needs or nutrient totals.']},\n  plants:{title:'Try a little more variety.',body:'Different fruit, veg, pulses and wholegrains give you more ways to build a meal. One new choice is a useful start.',steps:['Swap in a vegetable you like or have available.','Include different food groups over the day; one recipe is not a complete diet.']}\n },\n recipes:[\n  {id:'porridge',meal:'breakfast',title:'Banana porridge',description:'Warm oats, a familiar topping and very little washing-up.',minutes:10,cupboard:true,base:[['oats','Porridge oats','40g'],['banana','Banana','1']],variants:[{id:'milk',name:'With milk',diets:['mixed','vegetarian'],items:[['milk','Milk','200ml']]},{id:'soya',name:'With fortified unsweetened soya drink',diets:['mixed','vegetarian','vegan'],items:[['soya','Fortified unsweetened soya drink','200ml']]}],method:['Put the oats and your chosen milk or drink in a pan. Cook gently, stirring, following the oats’ pack instructions.','Slice the banana over the porridge. Add a little water if you prefer it looser.'],tip:'Swap the banana for fruit you have. Check that plant drinks are fortified; their protein and nutrient content varies.'},\n  {id:'toast',meal:'breakfast',title:'Breakfast on toast',description:'A warm topping, wholemeal toast and tomatoes alongside.',minutes:12,cupboard:true,base:[['bread','Wholemeal bread','1–2 slices'],['tomatoes','Tomatoes','a handful']],variants:[{id:'eggs',name:'Scrambled eggs',diets:['mixed','vegetarian'],items:[['eggs','Eggs','2'],['oil','Rapeseed or olive oil','a little']],step:'Warm a little oil in a pan. Add beaten eggs and stir until fully set.'},{id:'beans',name:'Warm beans',diets:['mixed','vegetarian','vegan'],items:[['beans','Tinned beans in tomato sauce','about half a tin']],step:'Heat the beans following the pack instructions.'},{id:'tofu',name:'Tofu scramble',diets:['mixed','vegetarian','vegan'],items:[['tofu','Firm tofu','about 100g'],['oil','Rapeseed or olive oil','a little']],step:'Crumble tofu into a pan with a little oil. Cook following its pack instructions; add seasoning you enjoy.'}],method:['Toast the bread and wash and chop the tomatoes.','{variant}','Serve the topping on the toast, with the tomatoes alongside.'],tip:'Adjust the slices and topping to your appetite and needs. The variants are not nutritionally interchangeable.'},\n  {id:'overnight',meal:'breakfast',title:'Overnight oats & berries',description:'Put it together tonight; breakfast is ready to pick up.',minutes:5,cupboard:false,base:[['oats','Porridge oats','40g'],['berries','Fresh or frozen berries','a handful']],variants:[{id:'yoghurt',name:'Plain yoghurt',diets:['mixed','vegetarian'],items:[['yoghurt','Plain yoghurt','about 150g']]},{id:'soya-yoghurt',name:'Fortified plain soya yoghurt',diets:['mixed','vegetarian','vegan'],items:[['soya-yoghurt','Fortified plain soya yoghurt','about 150g']]}],method:['Mix oats and yoghurt in a covered container. Add a splash of water for a looser texture.','Add berries prepared according to their pack instructions. Some frozen fruit requires cooking first.','Refrigerate overnight and keep chilled until you eat it. Follow the ingredients’ storage instructions.'],tip:'Five minutes is hands-on time; chilling is extra. Banana or chopped apple works too.'},\n  {id:'jacket',meal:'lunch',title:'Loaded jacket potato',description:'A skin-on potato, a useful topping and a bit of veg.',minutes:20,cupboard:true,base:[['potato','Potato','1 medium'],['mixed-veg','Frozen mixed vegetables','a handful']],variants:[{id:'beans',name:'Warm beans',diets:['mixed','vegetarian','vegan'],items:[['beans','Tinned beans in tomato sauce','about half a tin']],step:'Heat the beans and frozen vegetables following their pack instructions.'},{id:'tuna',name:'Tuna',diets:['mixed'],items:[['tuna','Tinned tuna','1 small tin, drained']],step:'Cook the frozen vegetables following the pack instructions. Drain the tuna.'}],method:['Wash and pierce the potato. Microwave following your appliance instructions, turning if needed, until fully cooked. An oven takes longer.','{variant}','Split the potato and add the topping. Serve the vegetables alongside.'],tip:'The estimate assumes a microwave. Swap the veg for a washed salad if you have one.'},\n  {id:'wrap',meal:'lunch',title:'Crunchy lunch wrap',description:'A simple filling you can take to work or eat at home.',minutes:10,cupboard:false,base:[['wrap','Wholemeal wrap','1'],['carrot','Carrot','1 small'],['cucumber','Cucumber','a few slices']],variants:[{id:'hummus',name:'Hummus & chickpeas',diets:['mixed','vegetarian','vegan'],items:[['hummus','Hummus','2 tablespoons'],['chickpeas','Tinned chickpeas','about half a tin, drained']],step:'Spread hummus over the wrap and add chickpeas prepared according to their pack instructions.'},{id:'egg',name:'Egg & yoghurt',diets:['mixed','vegetarian'],items:[['eggs','Eggs','2'],['yoghurt','Plain yoghurt','1 tablespoon']],step:'Hard-boil the eggs until cooked through. Cool, peel and chop; mix with yoghurt and add to the wrap.'}],method:['Wash the vegetables. Grate the carrot and slice the cucumber.','{variant}','Add the vegetables, fold the sides in and roll. Keep chilled if you are taking it out.'],tip:'Hummus commonly contains sesame. Check labels. The egg version takes longer if boiling from scratch.'},\n  {id:'couscous',meal:'lunch',title:'Couscous bowl',description:'A kettle, a bowl and something useful from the cupboard.',minutes:12,cupboard:true,base:[['couscous','Wholewheat couscous','about 50g dry'],['tomatoes','Tomatoes','a handful'],['oil','Rapeseed or olive oil','a little']],variants:[{id:'lentils',name:'Tinned lentils',diets:['mixed','vegetarian','vegan'],items:[['lentils','Tinned lentils','about half a tin, drained']]},{id:'chickpeas',name:'Tinned chickpeas',diets:['mixed','vegetarian','vegan'],items:[['chickpeas','Tinned chickpeas','about half a tin, drained']]}],method:['Make couscous following the pack instructions.','Wash and chop the tomatoes. Prepare the pulses according to their pack instructions.','Fluff the couscous and stir in the pulses, tomatoes and a little oil. Add lemon or seasoning if you have it.'],tip:'Use cooked frozen veg instead of tomatoes if that is what you have. Couscous contains wheat.'},\n  {id:'pasta',meal:'dinner',title:'Tomato & pulse pasta',description:'A straightforward sauce for the pasta already in your cupboard.',minutes:20,cupboard:true,base:[['pasta','Wholewheat pasta','about 75g dry'],['tinned-tomatoes','Tinned chopped tomatoes','about half a tin'],['mixed-veg','Frozen mixed vegetables','a handful']],variants:[{id:'lentils',name:'Tinned lentils',diets:['mixed','vegetarian','vegan'],items:[['lentils','Tinned lentils','about half a tin, drained']]},{id:'beans',name:'Tinned mixed beans',diets:['mixed','vegetarian','vegan'],items:[['mixed-beans','Tinned mixed beans','about half a tin, drained']]}],method:['Cook pasta following the pack instructions.','Combine tomatoes, prepared pulses and frozen vegetables in another pan. Add a splash of water and simmer until fully cooked, following the vegetables’ pack instructions.','Drain pasta and stir through the sauce. Add herbs or seasoning you already have.'],tip:'Follow safe cooling, refrigeration and reheating advice if making extra. Do not leave cooked food sitting out.'},\n  {id:'rice',meal:'dinner',title:'Simple rice & veg bowl',description:'A pan of vegetables and a topping that fits how you eat.',minutes:25,cupboard:false,base:[['rice','Brown rice','about 60g dry'],['mixed-veg','Frozen mixed vegetables','a handful'],['oil','Rapeseed or olive oil','a little']],variants:[{id:'tofu',name:'Tofu',diets:['mixed','vegetarian','vegan'],items:[['tofu','Firm tofu','about 100g']],step:'Cut tofu into cubes and cook in a little oil following its pack instructions.'},{id:'chicken',name:'Chicken',diets:['mixed'],items:[['chicken','Boneless chicken','about 100–150g']],step:'Keep raw chicken separate from other food. Cook in a little oil, following its pack instructions, until thoroughly cooked. Wash hands and clean utensils and surfaces used for raw chicken.'}],method:['Cook rice following the pack instructions; some brown rice takes longer than the estimate.','{variant}','Cook frozen vegetables as instructed on the pack. Combine with rice and the topping, adding seasoning you enjoy.'],tip:'A microwave rice pouch can shorten the cooking. If keeping cooked rice, follow specific safe rice storage advice.'},\n  {id:'curry',meal:'dinner',title:'Easy cupboard curry',description:'A gentle cupboard curry with wholemeal pitta alongside.',minutes:20,cupboard:true,base:[['tinned-tomatoes','Tinned chopped tomatoes','about half a tin'],['spinach','Frozen spinach','a handful'],['pitta','Wholemeal pitta','1'],['curry-powder','Curry powder','to taste']],variants:[{id:'chickpeas',name:'Chickpeas',diets:['mixed','vegetarian','vegan'],items:[['chickpeas','Tinned chickpeas','about half a tin, drained']]},{id:'lentils',name:'Lentils',diets:['mixed','vegetarian','vegan'],items:[['lentils','Tinned lentils','about half a tin, drained']]}],method:['Put tomatoes, prepared pulses and a little curry powder in a pan. Add a splash of water.','Add frozen spinach and simmer, stirring, until fully cooked following its pack instructions.','Warm the pitta and serve alongside. Start with mild seasoning if you prefer.'],tip:'Use mixed veg instead of spinach. Adjust seasoning and amount to what you tolerate and enjoy.'}\n ]\n};\n";
export const guideRuntime="(()=>{'use strict';\n const D=window.SHIFT_DATA,$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n const initial=()=>({goal:'basics',diet:'mixed',appetite:'usual',meal:'lunch',recipe:'jacket',variant:'beans',saved:[],chosen:null,checked:{},action:'meal',when:'This week'});\n let state=initial();\n const recipe=id=>D.recipes.find(r=>r.id===id);\n const variants=(r,diet=state.diet)=>r.variants.filter(v=>v.diets.includes(diet));\n const current=()=>({recipe:state.recipe,variant:state.variant});\n const key=p=>p.recipe+':'+p.variant;\n const valid=(p,diet=state.diet)=>!!recipe(p.recipe)?.variants.some(v=>v.id===p.variant&&v.diets.includes(diet));\n const variant=p=>recipe(p.recipe).variants.find(v=>v.id===p.variant);\n const title=p=>recipe(p.recipe).title+' · '+variant(p).name;\n const ingredients=p=>[...recipe(p.recipe).base,...variant(p).items];\n const method=p=>recipe(p.recipe).method.map(x=>x.replace('{variant}',variant(p).step||''));\n function ordered(meal=state.meal,goal=state.goal){return D.recipes.filter(r=>r.meal===meal&&variants(r).length).sort((a,b)=>goal==='budget'?Number(b.cupboard)-Number(a.cupboard)||a.minutes-b.minutes:goal==='quick'?a.minutes-b.minutes:0);}\n function shoppingPairs(ctx=state){const out=[...ctx.saved];if(ctx.chosen&&!out.some(p=>key(p)===key(ctx.chosen)))out.push(ctx.chosen);return out.length?out:[{recipe:ctx.recipe,variant:ctx.variant}];}\n function shopping(ctx=state){const groups=new Map();for(const p of shoppingPairs(ctx))for(const [id,label,amount]of ingredients(p)){if(!groups.has(id))groups.set(id,{id,label,uses:[]});groups.get(id).uses.push({meal:recipe(p.recipe).title,amount});}return [...groups.values()];}\n function announce(s){$('announcer').textContent=s;}\n function renderStart(){const g=D.goals[state.goal];let ctx='';if(state.diet==='vegan')ctx+='A vegan diet needs planning, including reliable B12 sources. These meal ideas do not cover every nutrient you need. <a href=\"'+D.sources.vegan.url+'\" target=\"_blank\" rel=\"noopener noreferrer\">NHS vegan guidance ↗</a> ';if(state.appetite==='glp1')ctx+='If a GLP-1 has reduced your appetite, keep meals regular and include protein foods. If eating is difficult or you feel unwell, contact your prescriber. <a href=\"'+D.sources.glp1.url+'\" target=\"_blank\" rel=\"noopener noreferrer\">BDA guidance ↗</a>';else if(state.appetite==='smaller')ctx+='Persistent low appetite or unexplained weight loss needs a GP assessment. Choosing this option does not establish a cause.';$('starting-result').innerHTML='<div><p class=\"eyebrow\">YOUR FOOD-FIRST START</p><h3>'+esc(g.title)+'</h3><p>'+esc(g.body)+'</p></div><div><p class=\"eyebrow\">ONE THING TO TRY</p><ul>'+g.steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><a class=\"text-link\" href=\"#food\">Choose a meal →</a></div>'+(ctx?'<p class=\"context-message\">'+ctx+'</p>':'');}\n function renderRecipes(reset=false){const list=ordered();if(reset||!list.some(r=>r.id===state.recipe))state.recipe=list[0].id;const r=recipe(state.recipe),vs=variants(r);if(!vs.some(v=>v.id===state.variant))state.variant=vs[0].id;$('recipe-choices').innerHTML=list.map(r=>'<button class=\"recipe-choice'+(r.id===state.recipe?' active':'')+'\" data-recipe=\"'+r.id+'\" aria-pressed=\"'+(r.id===state.recipe)+'\"><strong>'+esc(r.title)+'</strong><span>Approx. '+r.minutes+' min'+(r.cupboard?' · Cupboard friendly':'')+'</span></button>').join('');$('protein-swap').innerHTML=vs.map(v=>'<option value=\"'+v.id+'\"'+(v.id===state.variant?' selected':'')+'>'+esc(v.name)+'</option>').join('');renderMeal();}\n function renderMeal(){const p=current(),r=recipe(p.recipe);$('meal-time').textContent='APPROX. '+r.minutes+' MIN';$('meal-title').textContent=title(p);$('meal-description').textContent=r.description;$('meal-tags').innerHTML='<span class=\"tag\">'+esc(state.meal.toUpperCase())+'</span><span class=\"tag\">'+esc(state.diet==='mixed'?'YOUR FOOD CHOICE':state.diet.toUpperCase())+'</span>'+(r.cupboard?'<span class=\"tag\">CUPBOARD FRIENDLY</span>':'');$('ingredients').innerHTML=ingredients(p).map(([,l,q])=>'<li><strong>'+esc(l)+'</strong><span>'+esc(q)+'</span></li>').join('');$('method').innerHTML=method(p).map(x=>'<li>'+esc(x)+'</li>').join('');$('meal-tip').textContent=r.tip;const saved=state.saved.some(s=>key(s)===key(p));$('save-meal').textContent=saved?'Kept ✓':'Keep this idea +';$('save-meal').setAttribute('aria-pressed',String(saved));$('save-meal').disabled=!saved&&state.saved.length===3;$('meal-status').textContent=state.chosen&&key(state.chosen)===key(p)?'This meal is your next step.':state.saved.length===3&&!saved?'Three ideas kept. Remove one below to keep another.':'';renderShopping();renderPlan();}\n function renderShopping(){const pairs=shoppingPairs(),rows=shopping();$('saved-meals').innerHTML=state.saved.length?state.saved.map(p=>'<div class=\"saved-item\"><span>'+esc(title(p))+'</span><button class=\"text-button\" data-remove=\"'+key(p)+'\" aria-label=\"Remove '+esc(title(p))+'\">Remove</button></div>').join(''):'<p class=\"small\">No ideas kept yet. The list uses '+(state.chosen?'your chosen next step.':'your current meal.')+'</p>';$('clear-saved').hidden=!state.saved.length;$('shopping-scope').textContent=state.saved.length||state.chosen?'List covers '+pairs.length+' meal idea'+(pairs.length===1?'':'s')+', including your next step if chosen.':'Keep an idea or choose your next step to fix it in your list.';$('shopping-list').innerHTML=rows.map(({id,label,uses})=>'<label class=\"shopping-item\"><input type=\"checkbox\" data-shop=\"'+id+'\"'+(state.checked[id]?' checked':'')+'><span><strong>'+esc(label)+'</strong><small>'+uses.map(u=>esc(u.amount)+' · '+esc(u.meal)).join('<br>')+'</small></span></label>').join('');$('shopping-count').textContent=rows.filter(x=>!state.checked[x.id]).length+' of '+rows.length+' ingredients still to check. Amounts are shown per meal, not added together.';}\n const actions={meal:{title:'Make one useful meal.',body:'Try the meal below. Adjust the amount and ingredients to suit you.'},cupboard:{title:'Check the cupboard first.',body:'Tick what you have on the shopping list, then decide what you need.'},swap:{title:'Try one small swap.',body:'Choose a protein food, a wholegrain, or some fruit or veg to add variety to a meal you already eat.'},advice:{title:'Ask for individual advice.',body:'Take questions about appetite, dietary needs or difficulty eating to your GP, prescriber or a registered dietitian.'}};\n function renderPlan(){const a=actions[state.action],p=state.chosen||current();$('plan-title').textContent=a.title;$('plan-body').textContent=state.when+'. '+a.body+(state.action==='meal'?' Your idea: '+title(p)+'.':'');}\n function takeaway(ctx=state){const p=ctx.chosen||{recipe:ctx.recipe,variant:ctx.variant};return 'SHIFT SOME TIMBER — MY FOOD TAKEAWAY\\nContent checked: 12 October 2026\\n\\nFOCUS\\n'+D.goals[ctx.goal].title+'\\nDiet: '+ctx.diet+'; appetite: '+ctx.appetite+'\\n\\nMY NEXT STEP\\n'+actions[ctx.action].title+'\\n'+ctx.when+'. '+actions[ctx.action].body+'\\n\\nMEAL IDEA\\n'+title(p)+'\\nApprox. '+recipe(p.recipe).minutes+' minutes; equipment and ingredients vary.\\n\\nINGREDIENTS — ADJUST TO YOUR NEEDS\\n'+ingredients(p).map(([,l,q])=>'- '+l+': '+q).join('\\n')+'\\n\\nMETHOD\\n'+method(p).map((x,i)=>(i+1)+'. '+x).join('\\n')+'\\n'+recipe(p.recipe).tip+'\\n\\nKEPT IDEAS\\n'+(ctx.saved.length?ctx.saved.map(x=>'- '+title(x)).join('\\n'):'None yet.')+'\\n\\nSHOPPING / CUPBOARD CHECK\\n'+shopping(ctx).map(x=>'- '+(ctx.checked[x.id]?'[have] ':'[check] ')+x.label+' — '+x.uses.map(u=>u.amount+' ('+u.meal+')').join('; ')).join('\\n')+'\\n\\nUSE WITH CARE\\nGeneral adult meal ideas, not a complete daily diet or personal nutrition plan. Check allergens, cooking and storage instructions. Adjust amounts to your needs and appetite. Keep following clinical and dietary advice. Difficulty eating, persistent low appetite or unexplained weight loss needs assessment. If unwell while using a GLP-1, contact your prescriber.\\n\\nSOURCES\\n'+Object.values(D.sources).map(s=>s.name+'\\n'+s.url).join('\\n\\n')+'\\n\\nChoices stayed in this tab. Nothing was sent to SHIFT or saved to My Timber.\\n';}\n document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.sfgGoal){state.goal=b.dataset.sfgGoal;document.querySelectorAll('[data-sfg-goal]').forEach(x=>{const on=x.dataset.sfgGoal===state.goal;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on));});renderStart();renderRecipes();}if(b.dataset.sfgMeal){state.meal=b.dataset.sfgMeal;document.querySelectorAll('[data-sfg-meal]').forEach(x=>{const on=x.dataset.sfgMeal===state.meal;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on));});renderRecipes(true);}if(b.dataset.recipe){state.recipe=b.dataset.recipe;state.variant=variants(recipe(state.recipe))[0].id;renderRecipes();document.querySelector('[data-recipe=\"'+state.recipe+'\"]').focus();}if(b.dataset.remove){state.saved=state.saved.filter(p=>key(p)!==b.dataset.remove);renderMeal();$('save-meal').focus();announce('Meal idea removed.');}});\n $('diet').addEventListener('change',()=>{state.diet=$('diet').value;const removed=state.saved.filter(p=>!valid(p)).length;state.saved=state.saved.filter(p=>valid(p));if(state.chosen&&!valid(state.chosen))state.chosen=null;renderStart();renderRecipes();if(removed)announce(removed+' kept idea'+(removed===1?'':'s')+' removed to match your diet choice.');});\n $('appetite').addEventListener('change',()=>{state.appetite=$('appetite').value;renderStart();});\n $('protein-swap').addEventListener('change',()=>{state.variant=$('protein-swap').value;renderMeal();});\n $('save-meal').addEventListener('click',()=>{const p=current(),k=key(p);state.saved=state.saved.some(x=>key(x)===k)?state.saved.filter(x=>key(x)!==k):state.saved.length<3?[...state.saved,p]:state.saved;renderMeal();announce(state.saved.length+' of 3 meal ideas kept.');});\n $('use-meal').addEventListener('click',()=>{state.chosen=current();state.action='meal';document.querySelector('[name=\"action\"][value=\"meal\"]').checked=true;renderMeal();$('next').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$('plan-title').setAttribute('tabindex','-1');$('plan-title').focus({preventScroll:true});});\n $('shopping-list').addEventListener('change',e=>{if(e.target.dataset.shop){state.checked[e.target.dataset.shop]=e.target.checked;const rows=shopping();$('shopping-count').textContent=rows.filter(x=>!state.checked[x.id]).length+' of '+rows.length+' ingredients still to check. Amounts are shown per meal, not added together.';}});\n $('clear-saved').addEventListener('click',()=>{state.saved=[];renderMeal();$('save-meal').focus();announce('Kept ideas cleared. Your chosen next step is still available.');});\n $('action-options').addEventListener('change',e=>{if(actions[e.target.value]){state.action=e.target.value;renderPlan();}});$('when').addEventListener('change',()=>{state.when=$('when').value;renderPlan();});\n $('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([takeaway()],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='SHIFT-my-food-takeaway.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('download-status').textContent='Takeaway prepared. Your browser handles the download.';});\n $('print').addEventListener('click',()=>{let area=$('print-takeaway');if(!area){area=document.createElement('pre');area.id='print-takeaway';document.body.appendChild(area);}area.textContent=takeaway();window.print();});\n $('reset').addEventListener('click',()=>{state=initial();$('diet').value='mixed';$('appetite').value='usual';$('when').value='This week';$('download-status').textContent='';document.querySelector('[name=\"action\"][value=\"meal\"]').checked=true;document.querySelectorAll('[data-sfg-goal]').forEach(x=>{const on=x.dataset.sfgGoal==='basics';x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on));});document.querySelectorAll('[data-sfg-meal]').forEach(x=>{const on=x.dataset.sfgMeal==='lunch';x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on));});renderStart();renderRecipes();announce('All choices reset.');$('start').setAttribute('tabindex','-1');$('start').focus();});\n $('sources').innerHTML=Object.values(D.sources).map(s=>'<div class=\"source-item\"><a href=\"'+s.url+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+esc(s.name)+' ↗</a><span>'+esc(s.date)+'</span><p>'+esc(s.scope)+'</p></div>').join('');renderStart();renderRecipes();\n window.SHIFT_GUIDE={initial,ordered,variants,valid,ingredients,method,shopping,takeaway,getState:()=>structuredClone(state)};\n})();\n";
